import torch.nn as nn
import torch
import torch.nn.functional as F
import math

def _create_bigbird_mask(seq_len_q, seq_len_k, window_size, num_random_blocks, device):
    mask = torch.zeros(seq_len_q, seq_len_k, device=device)
    for i in range(seq_len_q):
        start = max(0, i - window_size // 2)
        end = min(seq_len_k, i + window_size // 2 + 1)
        mask[i, start:end] = 1
    if seq_len_q > 0:
        mask[0, :] = 1
        mask[-1, :] = 1
    if seq_len_k > 0:
        mask[:, 0] = 1
        mask[:, -1] = 1
    if num_random_blocks > 0:
        for i in range(1, seq_len_q - 1):
            if seq_len_k <= num_random_blocks:
                mask[i, :] = 1
            else:
                rand_indices = torch.randperm(seq_len_k, device=device)[:num_random_blocks]
                mask[i, rand_indices] = 1
    return mask

def run(query, key, value, window_size, num_random_blocks, scale=None, pse=None, sink=None):
    torch.manual_seed(42)
    b, n, sq, d_k = query.shape
    _, _, skv, _ = key.shape
    _, _, _, dv = value.shape
    scores = torch.matmul(query.float(), key.float().transpose(-2, -1))
    scale = scale or (1.0 / (d_k ** 0.5))
    scores = scores * scale
    mask = _create_bigbird_mask(sq, skv, window_size, num_random_blocks, query.device)
    mask = mask.unsqueeze(0).unsqueeze(0)
    scores = scores.masked_fill(mask == 0, -1e9)
    if pse is not None:
        pse = pse.to(scores.dtype)
        if pse.dim() == 4:
            scores = scores + pse
        elif pse.dim() == 2:
            scores = scores + pse.view(1, 1, 1, -1)
        else:
            scores = scores + pse
    if sink is not None:
        sink = sink.to(scores.dtype)
        scores = scores + sink.view(1, -1, 1, 1)
    attn_weights = F.softmax(scores, dim=-1)
    output = torch.matmul(attn_weights, value.float()).to(dtype=query.dtype)
    return output
